import { Category, ContactPointAddress, ContactPointEmail, ContactPointPhone, ErrorEvent, Identity, PartyIdentification, UserEngagement } from '../events';
/**
Description: A user updates their profile.
*/
export type UpdateUserProfile = {
    events: Array<UserEngagement | Identity | PartyIdentification | ContactPointEmail | ContactPointPhone | ContactPointAddress | ErrorEvent>;
}

export class UpdateUserProfileBuilder {

    private updateUserProfile: UpdateUserProfile = {
        events: []
    }

    private contactPointAddress!: ContactPointAddress;
    private contactPointEmail!: ContactPointEmail;
    private contactPointPhone!: ContactPointPhone;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;
    private userEngagement!: UserEngagement;

    public withContactPointAddress(contactPointAddress: ContactPointAddress) : UpdateUserProfileBuilder {
        this.contactPointAddress = contactPointAddress;
        return this;
    }
    public withContactPointEmail(contactPointEmail: ContactPointEmail) : UpdateUserProfileBuilder {
        this.contactPointEmail = contactPointEmail;
        return this;
    }
    public withContactPointPhone(contactPointPhone: ContactPointPhone) : UpdateUserProfileBuilder {
        this.contactPointPhone = contactPointPhone;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : UpdateUserProfileBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : UpdateUserProfileBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : UpdateUserProfileBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }
    public withUserEngagement(userEngagement: UserEngagement) : UpdateUserProfileBuilder {
        this.userEngagement = userEngagement;
        return this;
    }

    public build() : UpdateUserProfile {
        if(this.contactPointAddress) {
            this.updateUserProfile.events.push(this.contactPointAddress);
        }
        if(this.contactPointEmail) {
            this.updateUserProfile.events.push(this.contactPointEmail);
        }
        if(this.contactPointPhone) {
            this.updateUserProfile.events.push(this.contactPointPhone);
        }
        if(this.errorEvent) {
            this.updateUserProfile.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.updateUserProfile.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.updateUserProfile.events.push(this.partyIdentification);
        }
        if(this.userEngagement) {
            this.updateUserProfile.events.push(this.userEngagement);
        }

        return this.updateUserProfile;
    }
}
